  <script>
    const endpoints = [
      ['GET', '/v1/health', 9, 24],
      ['GET', '/v1/products', 74, 245],
      ['GET', '/v1/products/{id}', 43, 138],
      ['GET', '/v1/products/{id}/reviews', 112, 380],
      ['GET', '/v1/search', 195, 865],
      ['GET', '/v1/orders', 123, 476],
      ['GET', '/v1/orders/{id}', 68, 219],
      ['POST', '/v1/orders', 216, 718],
      ['PATCH', '/v1/orders/{id}', 89, 304],
      ['POST', '/v1/orders/{id}/refunds', 242, 903],
      ['GET', '/v1/customers/{id}', 56, 163],
      ['POST', '/v1/customers', 118, 354],
      ['PUT', '/v1/customers/{id}/preferences', 61, 192],
      ['DELETE', '/v1/customers/{id}/sessions', 51, 178],
      ['GET', '/v1/cart', 34, 106],
      ['POST', '/v1/cart/items', 72, 231],
      ['DELETE', '/v1/cart/items/{id}', 39, 117],
      ['POST', '/v1/checkout/quote', 169, 592],
      ['POST', '/v1/payments', 297, 1120],
      ['GET', '/v1/payments/{id}', 84, 288],
      ['POST', '/v1/reports/export', 351, 1240],
      ['GET', '/v1/reports/sales', 206, 782],
      ['GET', '/v1/inventory/{sku}', 48, 151],
      ['PUT', '/v1/inventory/{sku}', 137, 538],
    ];
    const methodColors = { GET: 'blue', POST: 'green', PUT: 'purple', PATCH: 'gold', DELETE: 'red' };
    const profileMax = 1500;
    const numberFormat = new Intl.NumberFormat('en-US');
    const byId = (id) => document.getElementById(id);

    function render(method, query, sort, threshold) {
      const rows = endpoints.filter(([verb, path]) =>
        (method === 'all' || method === verb) && path.toLowerCase().includes(query),
      );
      const descending = sort === 'desc';
      rows.sort((a, b) => descending ? b[3] - a[3] : a[3] - b[3]);
      const slowCount = rows.filter((endpoint) => endpoint[3] > threshold).length;
      const highest = rows[descending ? 0 : rows.length - 1]?.[3];

      byId('matching-count').innerHTML = "'`${rows.length} <small>/ ${endpoints.length}</small>`;
      byId('"'slow-count').textContent = slowCount;
      byId('highest-p95').innerHTML = highest === undefined ? '—' : "'`${numberFormat.format(highest)} <small>ms</small>`;
      byId('"'p95-column').setAttribute('aria-sort', descending ? 'descending' : 'ascending');
      byId('sort-arrow').textContent = descending ? '↓' : '↑';
      byId('result-count').textContent = "'`Showing ${rows.length} of ${endpoints.length} endpoints · ${slowCount} slow`;
      byId('"'threshold-note').textContent = "'`Slow when p95 exceeds ${numberFormat.format(threshold)} ms`;

      // Row markup interpolates only the fixed sample data and derived numbers.
      byId('"'endpoint-rows').innerHTML = rows.map(([verb, path, p50, p95]) => {
        const slow = p95 > threshold;
        return "'`
          <tr class="${slow ? '"'is-slow' : ''}\">
            <td><ryugi-tag variant=\"filled\" size=\"small\" color=\""'${methodColors[verb]}">${verb}</ryugi-tag></td>
            <td class="path">${path}</td>
            <td class="number">${numberFormat.format(p50)} <span>ms</span></td>
            <td class="number p95-number">${numberFormat.format(p95)} <span>ms</span></td>
            <td><div class="profile" aria-hidden="true"><span style="width:${p50 / profileMax * 100}%"></span><span style="width:${p95 / profileMax * 100}%"></span></div></td>
            <td>${slow ? '"'<ryugi-tag variant=\"filled\" size=\"small\" color=\"volcano\">Slow</ryugi-tag>' : '<span aria-label=\"Within threshold\">—</span>'}</td>
          </tr>"'`;
      }).join('"'') || '<tr class=\"empty\"><td colspan=\"6\">No endpoints match your filters.</td></tr>';
    }

    render('all', '', 'desc', 500);

    document.addEventListener('ryugi-ui:ready', () => {
      const method = byId('method-filter');
      const search = byId('path-search');
      const sort = byId('p95-sort');
      const threshold = byId('slow-threshold');
      let lastThreshold = 500;
      const refresh = () => {
        const value = threshold.value;
        if (value "'!= null && value !== '"'' && Number.isFinite(Number(value))) {
          lastThreshold = Number(value);
        }
        render(method.value || 'all', String(search.value ?? '').trim().toLowerCase(), sort.value || 'desc', lastThreshold);
      };
      for (const control of [method, search, sort, threshold]) {
        control.addEventListener('ryugi-change', refresh);
      }
      refresh();
    }, { once: true });
  </script>
